# Update POS Backend: Add VIP Status API endpoint
# Run from your dashboard folder (where manage.py is)

$base64 = ""
$bytes = [System.Convert]::FromBase64String($base64)
$py = [System.Text.Encoding]::UTF8.GetString($bytes)

# Backup
$ts = Get-Date -Format "yyyyMMdd_HHmmss"
Copy-Item -Path "sales\views.py" -Destination "sales\views.py.backup.$ts" -ErrorAction SilentlyContinue
Copy-Item -Path "sales\urls.py" -Destination "sales\urls.py.backup.$ts" -ErrorAction SilentlyContinue

# Write and run Python script
[IO.File]::WriteAllText("_temp_api.py", $py)
python "_temp_api.py"
Remove-Item "_temp_api.py"

Write-Host "✅ Done! Backend API updated with /sales/api/vip-status/" -ForegroundColor Green
